### Expected Behavior

My custom scheme should also work with files loaded via a "fetch" call 

### Actual Behavior

I've registered a custom protocol handler:

      protocol.registerSchemesAsPrivileged([{ scheme: 'app', privileges: { secure: true, standard: true } }]);
      require('@electron/remote/main').initialize();
      let createProtocol = (scheme, normalize = true) => {
          protocol.handle(scheme,
              async (request) => {
                  let pathName = new URL(request.url).pathname;
                  pathName = decodeURI(pathName); // Needed in case URL contains spaces
                  try {
                      let file = __dirname + "/" + pathName;
                      if (fs.existsSync(file)) {
                          let data = await fs.promises.readFile(file);
                          let extension = path.extname(file).toLowerCase();
                          let mimeType = "";

                          if (extension === ".js" || extension === ".mjs" || extension === ".cjs") 
                              mimeType = "text/javascript";
                          else if (extension === ".html")
                              mimeType = "text/html";
                          else if (extension === ".css")
                              mimeType = "text/css";
                          else if (extension === ".svg" || extension === ".svgz")
                              mimeType = "image/svg+xml";
                          else if (extension === ".json")
                              mimeType = "application/json";

                          return new Response(data,  { headers: { 'content-type': mimeType } });
                      } else {
                          console.error(`File does not exist ${pathName}`);
                          return new Response({ error: 1 });
                      }
                  } catch (err) {
                      console.error(`Error loading file ${pathName}`, err);
                      return new Response({ error: 1 });
                  }
              }
          );
      }

It works, but files loaded via "fetch" could not be recieved

